{"reply": "I've identified a pattern for your billing and invoice emails.",
 "proposed_rules": [
   {
    "name": "Invoices Filter",
    "match_mode": "any",
    "conditions": [
     {"field": "subject", "op": "contains", "value": "Invoice"},
     {"field": "subject", "op": "contains", "value": "Receipt"}
    ],
    "actions": {"move_to": "Invoices"},
    "placement": "bottom",
    "rationale": "Groups emails containing invoice or receipt keywords into the Invoices folder."
   }
 ]}

{"reply": "I have identified a pattern for protecting communications from Alice Chan to ensure they remain prioritized.",
 "proposed_rules": [
   {
    "name": "Protect Alice Communications",
    "match_mode": "all",
    "conditions": [
     {"field": "from", "op": "contains", "value": "alice.chan@westgate.example"}
    ],
    "actions": {},
    "placement": "top",
    "rationale": "Acts as a guard to ensure emails from this specific sender are not moved by other general rules."
   }
 ]}

